// Oracle differential compare (verify_oracle F2): field-wise diff of two
// drained hybrid_state_v1 records -- the QEMU oracle's exit-boundary drain
// (ref) against the hybrid run's vsim drain (got).
//
// Compare policy, fixed by what vsim's drain freshly reads (state_drain.hpp
// drain_with_passthrough):
//   strict:  magic/version/flags/hart_id/priv (identity), pc, gpr[0..31],
//            mepc/mcause (round-trip), mscratch (L23) + mtval/mie (L24) --
//            round-trip M-mode CSRs restored at resume + re-read at drain;
//            fpr[0..31] under FLAG_FP; vstart/vtype/vl/vlenb/vxsat/vxrm/vcsr
//            and the vreg bytes under FLAG_V.
//   skipped: mstatus, mtvec, medeleg, mideleg, mip, satp, pmpcfg[], pmpaddr[].
//            mtvec/medeleg/mideleg/satp/PMP are passthrough on the vsim side
//            (copied from QEMU1's ENTRY snapshot, never re-read). mip IS
//            re-read but excluded here -- its pending bits are hardware-driven
//            and diverge between the engines' clocks. mstatus is excluded for
//            its dirty/impl-defined bits.
//   masked:  mcycle, minstret -- the engines count cycles/insns differently
//            by design.
#ifndef ANDESIM_STATE_DIFF_HPP
#define ANDESIM_STATE_DIFF_HPP

#include <string>
#include <vector>

#include "hybrid/state_abi.h"

namespace andes_sim {

// One strictly-compared field that differs: "pc", "x5", "f31", "vl",
// "v3[7]" (register + byte offset), "flags", ...
struct FieldDiff {
  std::string field;
  unsigned long long ref = 0;
  unsigned long long got = 0;
};

struct DiffReport {
  int compared = 0;  // count of strictly compared fields
  std::vector<FieldDiff> diffs;
  bool ok() const { return diffs.empty(); }
};

// andes_supported: the cycle engine's --describe `andes_csrs` list (which Andes
// CSRs it implements). An Andes CSR not in the list is skipped: vsim never
// restored/re-read it (ResumeDriver/StateDrain gate on the same capability), so
// comparing it against the QEMU oracle would false-diff. The whole PMA block is
// gated by the "pmacfg"/"pmaaddr" group markers. Empty = no engine info ->
// compare every Andes CSR (the state-diff subcommand and unit tests).
DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got,
                       const std::vector<std::string>& andes_supported = {});

// Print `r` as "[state-diff] ..." lines: one per mismatch, then the
// PASS/FAIL verdict. Shared by the state-diff subcommand and run --verify.
void print_diff_report(const DiffReport& r);

// v6: names of mask-governed CSRs the program actually WROTE (per the drained
// write-mask) that `andes_supported` says the cycle engine does not implement.
// This combination is a real incompatibility signal: on that engine's silicon
// the csrw would trap at boot and the program would never reach the ROI, yet
// the hybrid restore silently skips it. The driver warns with these names.
// PMA reports as the group markers "pmacfg"/"pmaaddr". ucode is never reported
// (the plugin sets its bit unconditionally -- transport-always, not a real
// write record). Empty when the mask flag is clear (pre-v6 file) or the
// supported list is empty (no engine info).
std::vector<std::string> unsupported_written_csrs(
    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported);

// The stderr-ready warning line for unsupported_written_csrs: names the
// engine and the offending CSRs, newline-terminated. Empty string when there
// is nothing to report (clean run, pre-v6 file, or no engine info).
std::string unsupported_written_warning(
    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported,
    const std::string& engine_id);

}  // namespace andes_sim

#endif  // ANDESIM_STATE_DIFF_HPP

